'use strict';
/* Consoles : tous les montants, résultats, droits et états proviennent du serveur. */
(() => {
 const esc=x=>String(x??'Non disponible').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={principal:'Capital',payment_count:'Nombre d’échéances',first_due:'Première échéance',last_due:'Dernière échéance',first_instalment:'Première échéance — montant',maximum_instalment:'Échéance maximale',total_repayment:'Total des remboursements',total_credit_cost:'Coût total du crédit',annual_nominal_rate:'Taux nominal annuel',method:'Méthode',duration_months:'Durée en mois',fee_treatment:'Traitement des frais',explicit:'Échéancier explicite',cases:'Dossiers',analyses_in_period:'Analyses dans la période',approved_offers:'Offres favorables',registered_applicants:'Comptes demandeurs inscrits',bank_decision:'Décision bancaire',bank_received:'Réception bancaire confirmée',bank_account_invited:'Invitation de compte bancaire',delivery_attempt:'Tentative de transmission',sharing_confirmed:'Partage confirmé',sharing_prepared:'Partage préparé',attestation_issued:'Attestation émise',internal_decision:'Décision interne',internal_review_started:'Revue interne ouverte',review_access_requested:'Accès de revue demandé',applicant_assigned:'Demandeur rattaché',partner_activated:'Établissement activé',partner_connection_tested:'Connexion vérifiée',partner_created:'Établissement créé',institution_policy_configured:'Politique institutionnelle configurée',keys:'Clés',notice:'Information',partner_bound:'Liée à cet établissement',status:'Statut',cryptographic_valid:'Signature cryptographique valide',integrity_valid:'Intégrité du document valide',third_party_certification:'Certification par un tiers',not_verified:'Non vérifiée',demonstration:'Démonstration',issuer_id:'Institution émettrice',key_id:'Identifiant de clé',configured:'Signature configurée',public_key_base64:'Clé publique',purpose:'Usage',signature_configured:'Signature configurée',professional_name:'Identité professionnelle',function:'Fonction',bank:'Banque',microfinance:'Microfinance',preparation:'En préparation',active:'Actif',suspended:'Suspendu',temporarily_unavailable:'Indisponible',invited:'Invitation à activer',disabled:'Désactivé',deleted:'Supprimé',bank_agent:'Agent établissement',bank_manager:'Responsable décisionnaire',transmitted:'À réceptionner',received:'Réception confirmée',under_review:'En étude',additional_information:'Complément demandé',decision_available:'Décision disponible',withdrawn:'Retiré',issued_signed:'Signature émise',issued_unsigned:'Non signé',refused:'Refusé',revoked:'Révoqué',valid:'Signature vérifiée',invalid:'Signature non validée',unsigned:'Non signé',expired:'Expiré',approved:'Offre favorable',not_available:'Non disponible',not_applicable:'Non applicable',unfavorable:'Défavorable',unknown:'Inconnu',favorable:'Favorable',vigilance:'Vigilance',defavorable:'Défavorable',incomplete:'Incomplet',non_applicable:'Non applicable'};
 const label=x=>labels[x]||String(x??'Non disponible').replaceAll('_',' ');
 const date=x=>x?new Date(String(x).length===10?x+'T12:00:00Z':/[zZ]|[+-]\d\d:\d\d$/.test(String(x))?x:x+'Z').toLocaleDateString('fr-FR',{timeZone:'UTC',year:'numeric',month:'short',day:'numeric'}):'Non renseignée';
 const fields=(id,title,type='text',value='',extra='')=>`<label class="centre-field"><span>${esc(title)}</span><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const area=(id,title,value='',required=true)=>`<label class="centre-field"><span>${esc(title)}</span><textarea name="${id}" rows="3" ${required?'required':''}>${esc(value)}</textarea></label>`;
 const badge=x=>`<span class="centre-badge state-${esc(x)}">${esc(label(x))}</span>`;
 const btn=(text,id,kind='outline')=>`<button type="button" class="${kind}" id="${id}">${esc(text)}</button>`;
 const err=e=>{const target=document.querySelector('#centre-message');if(target){target.textContent=e.message;target.hidden=false;}else window.toast?.(e.message)};
 const api=()=>window.CreditServices?.api;let generation=0;const operations=new Map();let offset=0,days=30;
 const key=k=>{if(!operations.has(k))operations.set(k,crypto.randomUUID());return operations.get(k)};
 function title(t,s){document.querySelector('#page-title').textContent=t;document.querySelector('#page-subtitle').textContent=s;}
 const tabs=(items,current)=>`<nav class="centre-tabs" aria-label="Sections de l’espace">${items.map(([url,text])=>`<a href="#${url}" ${current===url?'aria-current="page"':''}>${text}</a>`).join('')}</nav>`;
 const panel=(title,body)=>`<section class="centre-panel"><h2>${title}</h2>${body}</section>`;
 function value(v){if(v===null||v===undefined)return 'Non disponible';if(typeof v==='boolean')return v?'Oui':'Non';if(typeof v==='object'&&Object.hasOwn(v,'state')&&Object.hasOwn(v,'value'))return v.value===null?esc(v.state==='not_applicable'?'Non applicable':'Inconnu'):esc(v.value);return esc(typeof v==='string'&&labels[v]?labels[v]:v);}
 function facts(data,depth=0){if(data===null||typeof data!=='object')return value(data);if(Array.isArray(data)){if(!data.length)return '<p class="centre-muted">Aucun élément renseigné.</p>';return '<div class="centre-facts-list">'+data.map(v=>'<div>'+facts(v,depth+1)+'</div>').join('')+'</div>';}return '<dl class="centre-facts">'+Object.entries(data).map(([k,v])=>'<div><dt>'+esc(label(k))+'</dt><dd>'+(v&&typeof v==='object'?facts(v,depth+1):value(v))+'</dd></div>').join('')+'</dl>';}
 async function download(path,name){const blob=await api().request(path,{responseType:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 async function printPreview(path){const win=window.open('about:blank','_blank');if(!win)throw Error('Autorisez l’ouverture de l’aperçu pour imprimer.');win.opener=null;try{const html=await api().request(path,{responseType:'text'});const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));win.onload=()=>{win.print()};win.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){win.close();throw e;}}
 function links(){const s=window.CreditServices;const menu=document.querySelector('#sections-dropdown'),navigation=document.querySelector('.nav-scroll');if(!menu||!navigation)return;for(const target of [menu,navigation]){for(const a of target.querySelectorAll('a:not([data-centre-link])'))a.hidden=false;for(const a of target.querySelectorAll('[data-centre-link]'))a.hidden=true;}if(!s?.ready)return;const user=s.user;const centre=location.hash.startsWith('#admin-centre')||location.hash==='#inbox'||['bank_agent','bank_manager'].includes(user.role);if(centre)for(const target of [menu,navigation])for(const a of target.querySelectorAll('a'))a.classList.remove('active');
 for(const [hash,text,show] of [['admin-centre/overview','Administration',user.role==='administrator'],['bank-inbox','Espace établissement',['bank_agent','bank_manager'].includes(user.role)],['inbox','Boîte de réception',user.role==='applicant']]){
  for(const target of [menu,navigation]){let a=target.querySelector('[data-centre-link="'+hash+'"]');if(!a){a=document.createElement('a');a.href='#'+hash;a.dataset.centreLink=hash;a.textContent=text;target.append(a);}a.hidden=!show;a.classList.toggle('active',location.hash==='#'+hash||(hash==='admin-centre/overview'&&location.hash.startsWith('#admin-centre'))||(hash==='bank-inbox'&&location.hash.startsWith('#bank-')));}
 }
 if(['bank_agent','bank_manager'].includes(user.role))for(const target of [menu,navigation])for(const a of target.querySelectorAll('a:not([data-centre-link])'))a.hidden=!['#profile','#settings'].includes(a.getAttribute('href'));
 }
 function hook(view,id,fn){const node=view.querySelector('#'+id);if(node)node.onclick=()=>Promise.resolve(fn()).catch(err);}
 function history(events){return '<ol class="centre-timeline">'+events.map(e=>'<li><span class="timeline-dot"></span><div><strong>'+esc(label(e.action))+'</strong><p>'+esc(date(e.created_at))+' · '+esc(e.actor_id||'Service')+'</p>'+(e.data?.reason?'<p>'+esc(e.data.reason)+'</p>':'')+'</div></li>').join('')+'</ol>'+(events.length?'':'<p>Aucun événement enregistré.</p>');}
 async function adminOverview(){const data=await api().request('/institution-admin/metrics?days='+days);const heading=['Centre d’administration.','Activité réelle de votre institution, établissements partenaires et contrôle des accès.'];const names={cases:'Dossiers enregistrés',analyses_in_period:'Analyses dans la période',transmissions:'Transmissions enregistrées',approved_offers:'Offres bancaires favorables',refusals:'Refus bancaires',registered_applicants:'Comptes demandeurs inscrits',managed_bank_accounts:'Accès établissements gérés',failed_deliveries:'Transmissions en échec'};const max=Math.max(0,...data.analysis_series.map(d=>d.analyses));
 return {heading,html:tabs([['admin-centre/overview','Activité'],['admin-centre/partners','Banques & microfinances']],'admin-centre/overview')+`<div class="centre-period"><label>Période <select id="centre-period">${[7,30,90,365].map(n=>`<option value="${n}" ${n===days?'selected':''}>${n} jours</option>`).join('')}</select></label><span>Actualisé le ${date(data.generated_at)}</span></div><div class="centre-stat-grid">${Object.entries(data.counters).map(([k,v])=>`<article class="centre-stat"><span>${esc(names[k]||label(k))}</span><strong>${v}</strong></article>`).join('')}</div>`+panel('Analyses enregistrées — nombre par jour',max?'<div class="centre-chart" role="img" aria-label="Nombre d’analyses par jour"><div>'+data.analysis_series.map(p=>`<span title="${esc(p.date)} : ${p.analyses}" style="height:${Math.max(2,p.analyses/max*100)}%"></span>`).join('')+'</div></div><p class="centre-muted">Du '+date(data.analysis_series[0].date)+' au '+date(data.analysis_series.at(-1).date)+'. Unité : analyses.</p><details><summary>Consulter les valeurs</summary>'+facts(data.analysis_series)+'</details>':'<div class="centre-empty">Aucune analyse enregistrée dans cette période.</div>')+`<div class="centre-columns">${panel('État des transmissions',facts(data.transmission_states))}${panel('Définitions des indicateurs',facts(data.definitions))}</div>`+panel('Historique récent des opérations',history(data.events)),bind(view){view.querySelector('#centre-period').onchange=e=>{days=Number(e.target.value);window.renderApp()}}};}
 function partnerForm(){return `<form id="centre-partner-create" class="centre-form"><div class="centre-form-grid">${fields('name','Dénomination de l’établissement','text','','required maxlength="200"')}<label class="centre-field"><span>Type d’établissement</span><select name="institution_type"><option value="bank">Banque</option><option value="microfinance">Microfinance</option></select></label>${fields('bank_institution_id','Identifiant institutionnel technique','text','','required maxlength="100"')}${fields('country','Pays — code ISO','text','BF','required minlength="2" maxlength="2"')}${fields('activity_scope','Activités et périmètre autorisés','text','','required')}${fields('products','Produits acceptés — identifiants séparés par des virgules','text','','required placeholder="personal_project, equipment"')}${fields('profiles','Profils acceptés','text','employee, retired, self_employed, structured_accounts, reconstructed_flows','required')}${fields('information_updated_on','Date de mise à jour des informations','date',new Date().toISOString().slice(0,10),'required')}</div>${area('presentation','Présentation autorisée')}${area('processing_notice','Finalité et information sur le traitement des dossiers')}${area('allowed_categories','Catégories de documents autorisées, séparées par des virgules','identification, credit_request, declaration, budget, debts, lender_report, analysis_summary, inventory, attestation, identity_card, payslip, employment_certificate, bank_statement, annual_financials')}${area('required_categories','Pièces exigées par cet établissement','identification, credit_request, lender_report, analysis_summary, attestation')}<p class="centre-muted">L’établissement est créé en préparation. Aucun dossier réel n’est transmis avant les vérifications, les références d’accord et son activation.</p><button class="primary" type="submit">Créer en préparation</button></form>`;}
 async function adminPartners(){const data=await api().request('/partners/admin/banks');const heading=['Banques & microfinances.','Créez les établissements, vérifiez leur connexion et gérez leurs accès sans effacer l’historique.'];return {heading,html:tabs([['admin-centre/overview','Activité'],['admin-centre/partners','Banques & microfinances']],'admin-centre/partners')+`<div class="institution-grid">${data.map(p=>`<article class="institution-card"><span class="institution-initial">${esc(p.name.slice(0,1))}</span>${badge(p.status)}<h2>${esc(p.name)}</h2><p>${esc(label(p.institution_type))} · ${esc(p.country)} · ${esc(p.reception_mode)}</p><p>${esc(p.presentation)}</p><a class="outline" href="#admin-centre/partner/${p.id}">Informations & comptes →</a></article>`).join('')||'<div class="centre-empty">Aucun établissement configuré.</div>'}</div>`+panel('Ajouter un établissement',partnerForm()),bind(view){view.querySelector('#centre-partner-create').onsubmit=async e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));for(const k of ['profiles','products','allowed_categories','required_categories'])values[k]=values[k].split(',').map(x=>x.trim()).filter(Boolean);values.cores=['individuals','businesses'];values.reception_mode='portal';values.demonstration=false;const b=form.querySelector('button[type=submit]');b.disabled=true;try{await api().request('/partners/admin/banks',{method:'POST',body:values});window.renderApp()}catch(error){err(error);b.disabled=false}}}};}
 async function adminPartner(id){const all=await api().request('/partners/admin/banks'),p=all.find(x=>x.id===id);if(!p)throw Error('Établissement introuvable.');const [accounts,signature]=await Promise.all([api().request('/institution-admin/partners/'+id+'/accounts'),api().request('/institution-admin/partners/'+id+'/signature')]);const heading=[p.name,'Paramétrage de l’établissement et comptes nominatifs. Les décisions restent réservées aux responsables habilités.'];
 return {heading,html:tabs([['admin-centre/overview','Activité'],['admin-centre/partners','Établissements']],'admin-centre/partners')+panel('Informations de l’établissement',`<div class="centre-badge-row">${badge(p.institution_type)}${badge(p.status)}${badge(p.connection_status)}</div><form id="centre-partner-edit" class="centre-form"><div class="centre-form-grid">${fields('name','Dénomination','text',p.name,'required')}<label class="centre-field"><span>Type</span><select name="institution_type"><option value="bank" ${p.institution_type==='bank'?'selected':''}>Banque</option><option value="microfinance" ${p.institution_type==='microfinance'?'selected':''}>Microfinance</option></select></label>${fields('country','Pays','text',p.country,'required minlength="2" maxlength="2"')}${fields('activity_scope','Périmètre','text',p.activity_scope,'required')}</div>${area('presentation','Présentation',p.presentation)}<p class="centre-muted">Une modification remet l’établissement en préparation : connexion et activation devront être reconfirmées.</p><button class="primary" type="submit">Enregistrer les informations</button></form>`)+panel('Connexion et activation',`<p>La vérification technique du portail ne remplace pas les accords juridiques ni le contrôle des représentants.</p>${btn('Vérifier le portail','centre-partner-test')}<form id="centre-partner-activate" class="centre-form"><div class="centre-form-grid">${fields('agreement_reference','Référence de l’accord de partenariat','text','','required')}${fields('representative_verification_reference','Vérification des représentants','text','','required')}${fields('data_sharing_reference','Accord de partage des données','text','','required')}${fields('legal_review_reference','Revue juridique du périmètre','text','','required')}</div><button class="primary" type="submit">Activer après vérifications</button></form><div class="centre-actions">${btn('Suspendre les nouvelles opérations','centre-partner-suspend')}${btn('Archiver cet établissement','centre-partner-delete','outline danger')}</div>`)+panel('Signature des offres', '<p>Une signature détachée protège l’intégrité du PDF et des conditions. Elle ne constitue pas une certification par un tiers.</p>'+facts(signature))+panel('Comptes de l’établissement',`<p>Un lien secret permet au titulaire de choisir son mot de passe. Aucun mot de passe bancaire existant n’est consultable.</p><div class="table-scroll"><table class="centre-table"><thead><tr><th>Identifiant</th><th>Fonction & rôle</th><th>État</th><th>Actions</th></tr></thead><tbody>${accounts.map(a=>`<tr><td>${esc(a.username)}<br><small>${esc(a.professional_name)}</small></td><td>${esc(a.function)}<br>${esc(label(a.role))}</td><td>${badge(a.status)}</td><td><div class="centre-actions"><button class="text-button" data-account-edit="${a.id}">Modifier</button><button class="text-button" data-account-reset="${a.id}">Réinitialiser l’accès</button><button class="text-button" data-account-disable="${a.id}" ${a.status==='invited'||a.status==='deleted'?'disabled':''}>${a.status==='invited'?'Activation requise':a.status==='active'?'Désactiver':'Réactiver'}</button><button class="text-button danger" data-account-delete="${a.id}">Supprimer</button></div></td></tr>`).join('')||'<tr><td colspan="4">Aucun compte géré pour cet établissement.</td></tr>'}</tbody></table></div><div id="centre-activation-result" hidden></div><form id="centre-account-create" class="centre-form"><h3>Ajouter un compte nominatif</h3><div class="centre-form-grid">${fields('username','Identifiant de connexion','text','','required maxlength="100"')}${fields('professional_name','Nom professionnel vérifié','text','','required maxlength="150"')}${fields('function','Fonction','text','','required maxlength="150"')}<label class="centre-field"><span>Rôle</span><select name="role"><option value="bank_agent">Agent : consulter et instruire</option><option value="bank_manager">Responsable : consulter et décider</option></select></label></div><button class="primary" type="submit">Créer et préparer l’activation</button></form>`),async bind(view){
 const activation=r=>{const box=view.querySelector('#centre-activation-result');box.hidden=false;box.innerHTML='<h3>Lien d’activation confidentiel</h3><p>'+esc(r.notice)+'</p><label class="centre-field"><span>À transmettre au titulaire — expire le '+date(r.expires_at)+'</span><input id="activation-secret" readonly value="'+esc(r.activation_url)+'"></label>'+btn('Copier le lien','copy-activation')+btn('Actualiser la liste après copie','refresh-accounts');hook(view,'refresh-accounts',()=>window.renderApp());hook(view,'copy-activation',async()=>{await navigator.clipboard.writeText(r.activation_url);toast('Lien copié.');});box.scrollIntoView({block:'center',behavior:'smooth'});};
 view.querySelector('#centre-account-create').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api().request('/institution-admin/partners/'+id+'/accounts',{method:'POST',body:Object.fromEntries(new FormData(e.target))});activation(r);b.textContent='Compte créé — actualiser la liste';e.target.reset()}catch(error){err(error);b.disabled=false}};
 view.querySelector('#centre-partner-edit').onsubmit=async e=>{e.preventDefault();try{await api().request('/institution-admin/partners/'+id,{method:'PATCH',body:{...Object.fromEntries(new FormData(e.target)),expected_version:p.version}});window.renderApp()}catch(error){err(error)}};
 hook(view,'centre-partner-test',async()=>{await api().request('/partners/admin/banks/'+id+'/test',{method:'POST',body:{}});window.renderApp()});
 view.querySelector('#centre-partner-activate').onsubmit=async e=>{e.preventDefault();try{await api().request('/partners/admin/banks/'+id+'/activate',{method:'POST',body:{...Object.fromEntries(new FormData(e.target)),expected_version:p.version}});window.renderApp()}catch(error){err(error)}};
 hook(view,'centre-partner-suspend',async()=>{await api().request('/partners/admin/banks/'+id+'/status',{method:'POST',body:{expected_version:p.version,status:'suspended',reason:'Suspension administrative des nouvelles opérations depuis le centre.'}});window.renderApp()});
 hook(view,'centre-partner-delete',async()=>{if(!confirm('Archiver cet établissement et désactiver ses comptes ? Les dossiers et documents historiques seront conservés.'))return;await api().request('/institution-admin/partners/'+id,{method:'DELETE',body:{expected_revision:p.version}});location.hash='admin-centre/partners'});
 for(const a of accounts){const change=async values=>{await api().request('/institution-admin/accounts/'+a.id,{method:'PATCH',body:{expected_revision:a.revision,...values}});window.renderApp()};view.querySelector('[data-account-disable="'+a.id+'"]').onclick=()=>change({status:a.status==='active'?'disabled':'active'}).catch(err);view.querySelector('[data-account-delete="'+a.id+'"]').onclick=()=>{if(confirm('Supprimer cet accès et révoquer ses sessions ? Son historique est conservé.'))change({status:'deleted'}).catch(err)};view.querySelector('[data-account-reset="'+a.id+'"]').onclick=async()=>{try{const r=await api().request('/institution-admin/accounts/'+a.id+'/reset',{method:'POST',body:{expected_revision:a.revision}});activation(r)}catch(error){err(error)}};view.querySelector('[data-account-edit="'+a.id+'"]').onclick=()=>{openModal(`<h2>Modifier l’accès</h2><form id="account-edit-modal" class="centre-form">${fields('professional_name','Nom professionnel','text',a.professional_name,'required')}${fields('function','Fonction','text',a.function,'required')}<label class="centre-field"><span>Habilitation</span><select name="role"><option value="bank_agent" ${a.role==='bank_agent'?'selected':''}>Agent établissement</option><option value="bank_manager" ${a.role==='bank_manager'?'selected':''}>Responsable décisionnaire</option></select></label><button class="primary" type="submit">Enregistrer</button></form>`,'ACCÈS ÉTABLISSEMENT');document.querySelector('#account-edit-modal').onsubmit=async e=>{e.preventDefault();try{await change(Object.fromEntries(new FormData(e.target)));document.querySelector('#modal').close()}catch(error){err(error)}};};}
 }};}
 async function bankInbox(current){const [list,workspace]=await Promise.all([api().request('/bank/inbox?limit=50&offset='+offset),api().request('/bank/workspace')]);const heading=[workspace.institutions[0]?.name||'Espace établissement.','Dossiers transmis à votre institution. Réception, instruction et décision sont enregistrées séparément.'];const filtered=current==='bank-history'?list.filter(t=>['decision_available','withdrawn'].includes(t.state)):list;
 return {heading,html:tabs([['bank-inbox','Réception & étude'],['bank-history','Historique des décisions']],current)+`<div class="centre-intro"><div><span class="mini-kicker">PORTAIL PARTENAIRE</span><h2>${esc(workspace.professional_name||label(workspace.role))}</h2><p>${esc(workspace.function||'Accès selon les habilitations de votre institution.')}</p></div><div>${badge(workspace.role)}<p class="centre-muted">Signature numérique : ${workspace.signature_configured?'clé active trouvée ; applicabilité vérifiée à l’émission':'à configurer par l’opérateur'}</p></div></div><div class="centre-tools"><label class="centre-field"><span>Rechercher dans cette page</span><input id="bank-filter" type="search" placeholder="Identifiant du dossier ou état"></label>${btn('Actualiser','bank-inbox-refresh')}</div><div class="bank-case-grid">${filtered.map(t=>`<article class="bank-case-card" data-bank-search="${esc((t.case_id+' '+label(t.state)).toLowerCase())}"><div class="centre-card-top">${badge(t.state)}<span>${esc(date(t.created_at))}</span></div><h2>Dossier ${esc(t.case_id.slice(0,8))}</h2><p>Version transmise ${t.case_version} · ${t.manifest.files.length} document(s) autorisé(s)</p><dl class="centre-facts"><div><dt>Validation interne</dt><dd>${esc(label(t.attestation_status))}</dd></div><div><dt>Décision bancaire</dt><dd>${esc(t.decision?label(t.decision.kind):'Non enregistrée')}</dd></div></dl><a class="primary" href="#bank-received/${t.id}">Consulter & instruire →</a></article>`).join('')||'<div class="centre-empty">Aucun dossier dans cette sélection.</div>'}</div><div class="centre-pagination">${btn('Page précédente','bank-previous')}${btn('Page suivante','bank-next')}</div><p class="centre-muted">La banque accède uniquement aux paquets effectivement transmis à son institution. Un dossier retiré reste identifiable dans l’historique selon sa réception antérieure.</p>`,bind(view){hook(view,'bank-inbox-refresh',()=>window.renderApp());view.querySelector('#bank-filter').oninput=e=>{const q=e.target.value.toLowerCase();for(const card of view.querySelectorAll('[data-bank-search]'))card.hidden=!card.dataset.bankSearch.includes(q)};view.querySelector('#bank-previous').disabled=offset===0;view.querySelector('#bank-next').disabled=list.length<50;hook(view,'bank-previous',()=>{offset=Math.max(0,offset-50);window.renderApp()});hook(view,'bank-next',()=>{offset+=50;window.renderApp()})}};}
 function decisionForm(t,workspace){if(workspace.role!=='bank_manager')return '<p>La décision et l’émission d’une offre sont réservées au responsable décisionnaire.</p>';return `<form id="centre-bank-decision" class="centre-form"><label class="centre-field"><span>Décision de l’établissement</span><select name="decision" id="centre-decision-kind"><option value="approved">Offre de financement favorable</option><option value="refused">Refus</option></select></label>${area('public_reason','Motif à communiquer au demandeur')}<fieldset id="centre-terms"><legend>Conditions fournies par l’établissement</legend><div class="centre-form-grid">${fields('reference','Référence de l’offre','text','','required')}${fields('product','Produit de financement','text','','required')}${fields('principal','Montant financé — FCFA / XOF','number','','required min="0.01" step="0.01"')}${fields('annual_rate_percent','Taux nominal annuel — %','number','','required min="0" max="1000" step="0.000001"')}${fields('months','Nombre d’échéances (mensuelles si générées)','number','','required min="1" max="600" step="1"')}${fields('disbursement_date','Date prévisionnelle de décaissement','date','','required')}${fields('first_due_date','Première échéance','date','','required')}${fields('validity_until','Offre valable jusqu’au','date','','required')}${fields('fee_per_payment','Frais par échéance (générateur) — FCFA','number','','required min="0" step="0.01"')}${fields('upfront_fees','Frais initiaux séparés — FCFA','number','','required min="0" step="0.01"')}${fields('insurance_cost','Coût d’assurance chiffré — FCFA','number','','required min="0" step="0.01"')}${fields('signatory_name','Nom du signataire habilité','text',workspace.professional_name||'','required '+(workspace.professional_name?'readonly':''))}${fields('signatory_function','Fonction du signataire','text',workspace.function||'','required '+(workspace.function?'readonly':''))}</div>${area('insurance','Assurance : garanties, exclusions et modalités')}${area('collateral','Garanties et engagements exigés')}${area('disbursement_conditions','Conditions préalables au décaissement')}${area('payment_method','Modalités et canal de remboursement')}${area('early_repayment','Remboursement anticipé')}${area('late_payment','Retards, pénalités et frais éventuels')}<details><summary>Échéancier irrégulier fourni par la banque (optionnel)</summary>${area('schedule','Échéancier JSON : date, principal, interest, fees — montants sous forme de chaînes','',false)}<p class="centre-muted">Sinon, le serveur génère des échéances mensuelles au taux nominal annuel divisé par douze, avec ajustement de la dernière. Aucun taux effectif réglementaire n’est calculé.</p></details><label class="centre-field"><span>Émission du document</span><select name="signature_mode"><option value="detached">Signature cryptographique détachée — clé bancaire requise</option><option value="unsigned">Document NON SIGNÉ — statut visible par le client</option></select></label><p class="centre-muted">Aucune certification par un tiers n’est revendiquée. Sans clé configurée, l’émission signée est refusée ; aucun remplacement silencieux par un document non signé.</p>${btn('Prévisualiser les conditions et calculer le coût','centre-preview-terms')}<div id="centre-cost-preview" hidden></div></fieldset><label class="centre-check"><input name="confirmed" type="checkbox" required> Je confirme la décision, le motif et, pour une offre, les conditions prévisualisées.</label><button class="primary" type="submit">Enregistrer la décision et notifier le client</button><p id="centre-decision-error" role="alert"></p></form>`;}
 function renderSections(report){return `<div class="centre-report-summary">${esc(report.summary)}</div><div class="centre-columns">${panel('Situation financière calculée',facts(report.financial_risk))}${panel('Qualification et limites',facts(report.scoring))}</div>`+(report.missing_information?.length?panel('Informations manquantes','<ul>'+report.missing_information.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'):'')+report.sections.map(s=>`<details class="centre-analysis-section"><summary><span>${esc(s.title)}</span>${badge(s.status)}</summary><p>${esc(s.explanation)}</p>${s.alerts?.length?'<ul>'+s.alerts.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}<div class="table-scroll"><table class="centre-table"><thead><tr><th>Indicateur</th><th>Période</th><th>Valeur / unité</th><th>Formule</th></tr></thead><tbody>${s.indicators.map(i=>`<tr><td>${esc(label(i.id))}</td><td>${i.period?date(i.period):'Périmètre de l’analyse'}</td><td>${value(i.value)} ${esc(i.unit)}</td><td>${esc(i.formula)}</td></tr>`).join('')}</tbody></table></div><details><summary>Règles, seuils et sources</summary>${facts({rules:s.rules,data_used:s.data_used,strengths:s.strengths,periods:s.periods,score:s.score,score_validation_status:s.score_validation_status,missing_information:s.missing_information,suggestion_ids:s.suggestion_ids})}</details></details>`).join('')+panel('Suggestions, scénarios et versions',facts({suggestions:report.suggestions,deep_analysis:report.deep_analysis,versions:report.versions,sources:report.sources,assumptions:report.assumptions,financing_conditions:report.financing_conditions}));}
 async function bankDetail(id){const prefix='/bank/transmissions/'+encodeURIComponent(id);const [t,events,workspace,analysis,decision]=await Promise.all([api().request(prefix),api().request(prefix+'/events'),api().request('/bank/workspace'),api().request(prefix+'/analysis'),api().request(prefix+'/agreement')]);const heading=['Instruction du dossier.','Version '+t.case_version+' transmise à votre établissement. Les résultats historiques ne sont pas recalculés.'];const panels=[['overview','Réception'],['analysis','Analyse détaillée'],['documents','Documents & approbation'],['decision','Décision bancaire'],['history','Historique']];
 const html=`<a class="text-button" href="#bank-inbox">← Boîte de réception</a><div class="centre-intro"><div><span class="mini-kicker">${analysis.case_kind==='individuals'?'PARTICULIER':'ENTREPRISE / PME'} · DOSSIER ${esc(t.case_id)}</span><h2>${esc(t.partner_name)}</h2><div class="centre-badge-row">${badge(t.state)}${badge(t.attestation_status)}${t.demonstration?badge('DÉMONSTRATION'):''}</div></div><div class="centre-actions">${btn('Actualiser','bank-refresh')}${btn('Vérifier l’attestation et les empreintes','bank-verify')}${btn('Télécharger le paquet complet autorisé','bank-archive')}</div></div><nav class="centre-tabs" role="tablist" aria-label="Instruction du dossier">${panels.map(([key,text],i)=>`<button type="button" role="tab" id="bank-tab-${key}" data-bank-panel="${key}" aria-controls="bank-panel-${key}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${text}</button>`).join('')}</nav>
 <section id="bank-panel-overview" class="centre-panel" role="tabpanel" aria-labelledby="bank-tab-overview"><h2>Réception et suivi</h2><div id="bank-verification-result"></div>${facts({conditions_analysées:t.financing,état_attestation:t.attestation_status,informations_à_compléter:analysis.report.missing_information})}<form id="bank-event-form" class="centre-form"><div class="centre-form-grid"><label class="centre-field"><span>Nouvel état</span><select name="action"><option value="received">Confirmer la réception</option><option value="under_review">Mettre en étude</option><option value="additional_information">Demander un complément</option></select></label>${fields('reason','Motif / message au demandeur','text','','required minlength="5"')}</div>${area('requested','Compléments demandés — une ligne par élément','',false)}<button class="primary" type="submit">Enregistrer cet événement</button><p id="bank-event-error" role="alert"></p></form></section>
 <section id="bank-panel-analysis" role="tabpanel" aria-labelledby="bank-tab-analysis" hidden>${renderSections(analysis.report)}</section>
 <section id="bank-panel-documents" class="centre-panel" role="tabpanel" aria-labelledby="bank-tab-documents" hidden><h2>Pièces du paquet transmis</h2><p>Fiches, rapport détaillé, synthèse, attestation de validation interne et justificatifs effectivement partagés. L’inventaire ne signifie pas que toutes les pièces sont authentifiées.</p><div class="centre-document-grid">${t.manifest.files.map(f=>`<article class="centre-document-card"><span class="document-symbol">PDF / PIÈCE</span><h3>${esc(label(f.category))}</h3><p>${esc(f.media_type||'Document')} · empreinte conservée</p><button class="outline" data-packet-file="${f.id}" id="packet-file-${f.id}">Télécharger</button></article>`).join('')}</div><details><summary>Manifeste, versions et empreintes</summary>${facts(t.manifest)}</details><h3>Documents de réponse partagés</h3>${t.attachments.map(f=>`<p>${esc(label(f.category))} · <button class="text-button" data-response-file="${f.id}">Télécharger</button></p>`).join('')||'<p>Aucun document de réponse partagé.</p>'}</section>
 <section id="bank-panel-decision" class="centre-panel" role="tabpanel" aria-labelledby="bank-tab-decision" hidden><h2>Décision et document bancaire</h2>${decision?`<div class="centre-badge-row">${badge(decision.decision)}${badge(decision.verification?.status||decision.state)}</div><p>${esc(decision.public_reason)}</p>${decision.terms?facts({montant:decision.terms.principal,devise:decision.terms.currency,coût_total:decision.terms.total_credit_cost,total_à_payer:decision.terms.total_due}):''}<div class="centre-actions">${decision.sha256?btn('Télécharger l’accord PDF','bank-agreement-pdf')+btn('Aperçu / Imprimer','bank-agreement-print')+btn('Vérifier la signature','bank-agreement-verify'):''}${decision.state!=='revoked'&&decision.sha256?btn('Révoquer cette offre','bank-agreement-revoke','outline danger'):''}</div><div id="bank-signature-result"></div>`:decisionForm(t,workspace)}</section>
 <section id="bank-panel-history" class="centre-panel" role="tabpanel" aria-labelledby="bank-tab-history" hidden><h2>Historique horodaté</h2>${history(events)}</section>`;
 return {heading,html,bind(view){const selectPanel=key=>{for(const [name] of panels){view.querySelector('#bank-panel-'+name).hidden=name!==key;const b=view.querySelector('#bank-tab-'+name);b.setAttribute('aria-selected',String(name===key));b.tabIndex=name===key?0:-1;}};view.querySelectorAll('[data-bank-panel]').forEach((b,i)=>{b.onclick=()=>selectPanel(b.dataset.bankPanel);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const index=(i+(e.key==='ArrowRight'?1:-1)+panels.length)%panels.length;selectPanel(panels[index][0]);view.querySelector('#bank-tab-'+panels[index][0]).focus()}});
 hook(view,'bank-refresh',()=>window.renderApp());hook(view,'bank-verify',async()=>{const result=await api().request(prefix+'/verify');view.querySelector('#bank-verification-result').innerHTML=facts(result)});hook(view,'bank-archive',()=>download(prefix+'/archive','dossier-'+t.case_id+'.zip'));view.querySelectorAll('[data-packet-file]').forEach(b=>b.onclick=()=>download(prefix+'/files/'+b.dataset.packetFile,'piece-'+b.dataset.packetFile).catch(err));view.querySelectorAll('[data-response-file]').forEach(b=>b.onclick=()=>download(prefix+'/attachments/'+b.dataset.responseFile,'reponse-bancaire.pdf').catch(err));
 if(decision){view.querySelector('#bank-event-form').hidden=true;}view.querySelector('#bank-event-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const body={expected_revision:t.revision,action:f.get('action'),reason:f.get('reason'),requested_information:String(f.get('requested')||'').split('\n').filter(x=>x.trim())};try{await api().request(prefix+'/events',{method:'POST',body,key:key('event:'+id+JSON.stringify(body))});window.renderApp()}catch(error){view.querySelector('#bank-event-error').textContent=error.message}};
 const form=view.querySelector('#centre-bank-decision');if(form){let preview=null;const kind=view.querySelector('#centre-decision-kind');kind.onchange=()=>{view.querySelector('#centre-terms').disabled=kind.value==='refused';view.querySelector('#centre-terms').hidden=kind.value==='refused';preview=null};form.oninput=event=>{if(event.target.name==='confirmed')return;preview=null;const box=view.querySelector('#centre-cost-preview');box.hidden=true};const body=()=>{const raw=Object.fromEntries(new FormData(form));let terms=null;if(raw.decision==='approved'){terms={};for(const k of ['reference','product','principal','annual_rate_percent','disbursement_date','first_due_date','validity_until','fee_per_payment','upfront_fees','insurance_cost','signatory_name','signatory_function','insurance','collateral','disbursement_conditions','payment_method','early_repayment','late_payment'])terms[k]=raw[k];terms.months=Number(raw.months);terms.currency='XOF';try{terms.schedule=raw.schedule.trim()?JSON.parse(raw.schedule):[]}catch{throw Error('Échéancier JSON invalide : utilisez les dates et montants exacts au format indiqué.')}}return {expected_revision:t.revision,decision:raw.decision,public_reason:raw.public_reason,signature_mode:raw.signature_mode||'unsigned',terms,preview_sha256:preview?.terms_sha256||null}};
 hook(view,'centre-preview-terms',async()=>{const confirmed=form.elements.confirmed;const wasRequired=confirmed.required;confirmed.required=false;const valid=form.reportValidity();confirmed.required=wasRequired;if(!valid)return;const result=await api().request(prefix+'/decision-preview',{method:'POST',body:body()});preview=result;const box=view.querySelector('#centre-cost-preview');box.hidden=false;box.innerHTML='<h3>Conditions calculées par le serveur</h3>'+facts({montant_financé:result.terms.principal,intérêts_totaux:result.terms.total_interest,frais_et_assurance:result.terms.total_fees_and_insurance,coût_total_du_crédit:result.terms.total_credit_cost,total_à_payer:result.terms.total_due,dernière_échéance:result.terms.last_due_date})+'<p>Devise : FCFA / XOF. Toute modification requiert une nouvelle prévisualisation.</p>';});
 form.onsubmit=async e=>{e.preventDefault();try{if(kind.value==='approved'&&!preview)throw Error('Prévisualisez les conditions et leur coût avant de confirmer.');const payload=body();const button=form.querySelector('button[type=submit]');button.disabled=true;await api().request(prefix+'/decision',{method:'POST',body:payload,key:key('decision:'+id+JSON.stringify(payload))});window.renderApp()}catch(error){view.querySelector('#centre-decision-error').textContent=error.message;form.querySelector('button[type=submit]').disabled=false}};
 }if(decision){hook(view,'bank-agreement-pdf',()=>download('/bank/agreements/'+decision.id+'/pdf','accord-'+decision.id+'.pdf'));hook(view,'bank-agreement-print',()=>printPreview('/bank/agreements/'+decision.id+'/preview'));hook(view,'bank-agreement-verify',async()=>{const result=await api().request('/bank/agreements/'+decision.id+'/signature');view.querySelector('#bank-signature-result').innerHTML=facts(result.verification)});hook(view,'bank-agreement-revoke',async()=>{const reason=prompt('Motif de révocation communiqué au client (5 caractères minimum) :');if(!reason)return;await api().request('/bank/agreements/'+decision.id+'/revoke',{method:'POST',body:{reason}});window.renderApp()});}
 }};
 }
 async function inbox(){const data=await api().request('/inbox');const heading=['Votre boîte de réception.','Décisions et documents transmis par les établissements ayant reçu votre dossier.'];return {heading,html:panel('Messages des établissements',data.map(m=>`<article class="client-message"><div class="centre-card-top">${badge(m.decision.verification?.status||m.decision.state)}<span>${date(m.created_at)}</span></div><h2>${esc(m.title)}</h2><p>${esc(m.decision.public_reason)}</p><p>Dossier transmis ${esc(m.transmission_id.slice(0,8))} · ${m.read_at?'Consulté':'Nouveau message'}</p>${m.decision.terms?`<div class="client-offer-numbers"><div><span>Montant proposé · FCFA / XOF</span><strong>${esc(m.decision.terms.principal)}</strong></div><div><span>Coût total du crédit · FCFA / XOF</span><strong>${esc(m.decision.terms.total_credit_cost)}</strong></div></div><p>Offre valable jusqu’au ${date(m.decision.terms.validity_until)}. Consultez les conditions, garanties, assurance et échéances avant toute acceptation. Ce document ne prouve pas un décaissement.</p><div class="centre-actions"><button class="primary" data-client-pdf="${m.decision.id}">Télécharger le PDF</button><button class="outline" data-client-print="${m.decision.id}">Aperçu / Imprimer</button><button class="outline" data-client-signature="${m.decision.id}">Vérifier l’intégrité et la signature</button></div><div id="client-verification-${m.decision.id}"></div>`:''}${m.decision.verification?.status==='unsigned'?'<p class="centre-warning">Document non signé : demandez à l’établissement de régulariser sa signature. Aucune certification électronique par un tiers.</p>':''}<button class="text-button" data-message-read="${m.id}">Marquer comme consulté</button></article>`).join('')||'<div class="centre-empty">Aucune décision reçue. Les offres et refus apparaîtront ici après leur enregistrement par l’établissement.</div>'),bind(view){view.querySelectorAll('[data-client-pdf]').forEach(b=>b.onclick=()=>download('/agreements/'+b.dataset.clientPdf+'/pdf','accord-'+b.dataset.clientPdf+'.pdf').catch(err));view.querySelectorAll('[data-client-print]').forEach(b=>b.onclick=()=>printPreview('/agreements/'+b.dataset.clientPrint+'/preview').catch(err));view.querySelectorAll('[data-client-signature]').forEach(b=>b.onclick=async()=>{try{const result=await api().request('/agreements/'+b.dataset.clientSignature+'/signature');view.querySelector('#client-verification-'+b.dataset.clientSignature).innerHTML=facts(result.verification)}catch(error){err(error)}});view.querySelectorAll('[data-message-read]').forEach(b=>b.onclick=async()=>{try{await api().request('/inbox/'+b.dataset.messageRead+'/read',{method:'POST',body:{}});window.renderApp()}catch(error){err(error)}});}};}
 function route(view,current){links();const s=window.CreditServices;const bank=['bank_agent','bank_manager'].includes(s?.user?.role);const handled=current.startsWith('admin-centre')||current==='inbox'||(bank&&!['profile','settings'].includes(current));if(!handled)return false;const seq=++generation;view.innerHTML='<div class="centre-loading">Chargement de votre espace sécurisé…</div>';if(!s?.ready){view.innerHTML=panel('Connexion requise','<a class="primary" href="/login.html">Se connecter</a>');return true;}let task;if(current.startsWith('admin-centre')){task=current.startsWith('admin-centre/partner/')?adminPartner(current.split('/')[2]):current==='admin-centre/partners'?adminPartners():adminOverview();}else if(current==='inbox')task=inbox();else task=current.startsWith('bank-received/')?bankDetail(current.split('/')[1]):bankInbox(current==='bank-history'?'bank-history':'bank-inbox');
 Promise.resolve(task).then(result=>{if(seq!==generation||api()!==s.api||!s.ready||location.hash.slice(1)!==current)return;title(...result.heading);view.innerHTML='<p id="centre-message" class="centre-warning" role="alert" hidden></p>'+result.html;result.bind?.(view);window.CreditExperience?.enhance(view);window.CreditExperience?.moveNavigation();}).catch(error=>{if(seq!==generation||location.hash.slice(1)!==current||api()!==s.api)return;view.innerHTML=panel('Espace indisponible','<p>'+esc(error.message)+'</p>'+btn('Actualiser','centre-retry'));hook(view,'centre-retry',()=>window.renderApp())});return true;
 }
 window.CreditInstitutions={route,links};
})();
